#!/usr/bin/env python3

def sieve(n):
    is_prime = [True] * (n+1)
    is_prime[0:2] = [False, False]
    p = 2
    while p*p <= n:
        if is_prime[p]:
            step = p
            start = p*p
            for multiple in range(start, n+1, step):
                is_prime[multiple] = False
        p += 1
    return is_prime

def main():
    N = 10000
    is_prime = sieve(N)
    total = 0
    for n in range(2, N+1):
        if not is_prime[n]:  # composite
            if pow(2, n, n) == 2:
                total += n
    print(total)

if __name__ == "__main__":
    main()

