#!/usr/bin/env python3
# Find the smallest positive integer n such that n, n+1, and n+2 each have exactly 6 positive divisors.
# Program computes the answer by direct computation (no hard-coded answer).

import math
import sys

def sieve_primes(limit):
    sieve = bytearray(b"\x01") * (limit+1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(limit**0.5) + 1):
        if sieve[i]:
            step = i
            start = i*i
            sieve[start:limit+1:step] = b"\x00" * (((limit - start)//step) + 1)
    return [i for i, is_prime in enumerate(sieve) if is_prime]

def num_divisors(n, primes):
    orig = n
    total = 1
    for p in primes:
        if p*p > n:
            break
        if n % p == 0:
            exp = 0
            while n % p == 0:
                n //= p
                exp += 1
            total *= (exp + 1)
            if total > 6:  # early exit: we only care about equality to 6
                return total
        # tiny optimization: if n becomes 1 break
        if n == 1:
            break
    if n > 1:
        # remaining factor is prime
        total *= 2
    return total

def main():
    # Precompute primes up to a reasonable bound for trial division.
    # sqrt(max_n) for max_n up to ~1e10 is ~1e5. We'll use 200000 to be safe.
    primes = sieve_primes(200000)
    max_n = 10_000_000  # safety upper bound; should find solution well before this
    for n in range(1, max_n):
        if num_divisors(n, primes) == 6 and num_divisors(n+1, primes) == 6 and num_divisors(n+2, primes) == 6:
            print(n)
            return
    # If not found within max_n, extend search (rare). Increase bounds and continue.
    limit = max_n * 10
    # extend primes if needed
    max_prime_needed = int(math.isqrt(limit)) + 1
    if max_prime_needed > primes[-1]:
        primes = sieve_primes(max_prime_needed)
    for n in range(max_n, limit):
        if num_divisors(n, primes) == 6 and num_divisors(n+1, primes) == 6 and num_divisors(n+2, primes) == 6:
            print(n)
            return
    # If still not found, fail with no output (should not happen for reasonable bounds).
    sys.exit(1)

if __name__ == "__main__":
    main()

