def num_divisors(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    d = 1
    temp = n
    # count factor 2
    e = 0
    while temp % 2 == 0:
        temp //= 2
        e += 1
    if e:
        d *= (e + 1)
    # odd factors
    f = 3
    maxf = math.isqrt(temp) + 1
    while f <= maxf and temp > 1:
        if temp % f == 0:
            e = 0
            while temp % f == 0:
                temp //= f
                e += 1
            d *= (e + 1)
            maxf = math.isqrt(temp) + 1
        f += 2
    if temp > 1:
        d *= 2
    return d

