#!/usr/bin/env python3
# Find the smallest positive integer n such that n, n+1, and n+2 each have exactly 6 positive divisors.
# Direct computation without hard-coding the answer.

def sieve_primes(limit):
    sieve = bytearray(b'\x01') * (limit+1)
    sieve[0:2] = b'\x00\x00'
    for p in range(2, int(limit**0.5) + 1):
        if sieve[p]:
            step = p
            start = p*p
            sieve[start:limit+1:step] = b'\x00' * (((limit - start)//step) + 1)
    return [i for i, isprime in enumerate(sieve) if isprime]

PRIME_LIMIT = 100000  # primes up to 100k (enough to factor numbers up to ~1e10)
primes = sieve_primes(PRIME_LIMIT)

def num_divisors(n):
    orig = n
    total = 1
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            exp = 0
            while n % p == 0:
                n //= p
                exp += 1
            total *= (exp + 1)
            if total > 6:  # early exit if exceeds 6 (optimization)
                return total
    if n > 1:
        # n is prime (or a prime > PRIME_LIMIT). It contributes exponent 1.
        total *= 2
    return total

def main():
    n = 1
    while True:
        if num_divisors(n) == 6 and num_divisors(n+1) == 6 and num_divisors(n+2) == 6:
            print(n)
            return
        n += 1

if __name__ == "__main__":
    main()

