#!/usr/bin/env python3
import math
import sys

def sieve(n):
    bs = bytearray(b'\x01') * (n+1)
    bs[0:2] = b'\x00\x00'
    for p in range(2, int(n**0.5)+1):
        if bs[p]:
            step = p
            start = p*p
            bs[start:n+1:step] = b'\x00' * (((n - start)//step) + 1)
    return [i for i, val in enumerate(bs) if val]

PRIME_LIMIT = 200000
primes = sieve(PRIME_LIMIT)

def count_divisors(n):
    if n == 1:
        return 1
    orig = n
    total = 1
    for p in primes:
        if p*p > n:
            break
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            total *= (e+1)
            if total > 6:  # early exit: can't get back down to 6
                return total
        # small optimization: if n reduced to 1, break
    if n > 1:
        # remaining prime factor
        total *= 2
    return total

n = 1
while True:
    if count_divisors(n) == 6 and count_divisors(n+1) == 6 and count_divisors(n+2) == 6:
        print(n)
        break
    n += 1
