#!/usr/bin/env python3
# Find smallest positive integer n such that n, n+1, n+2 each have exactly 6 divisors.

import math
import sys

def primes_upto(n):
    if n < 2:
        return []
    sieve = bytearray(b'\x01') * (n + 1)
    sieve[0:2] = b'\x00\x00'
    lim = int(n**0.5)
    for i in range(2, lim + 1):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start:n+1:step] = b'\x00' * (((n - start) // step) + 1)
    return [i for i, isprime in enumerate(sieve) if isprime]

def find_triple(limit):
    primes = primes_upto(limit)
    pset = set(primes)
    six = set()
    # p^5
    for p in primes:
        v = p**5
        if v > limit:
            break
        six.add(v)
    # p^2 * q where p and q are distinct primes
    # iterate p with p^2 <= limit
    for p in primes:
        p2 = p * p
        if p2 > limit:
            break
        max_q = limit // p2
        # iterate primes q up to max_q
        # use primes list (primes is sorted)
        # break when q > max_q
        for q in primes:
            if q > max_q:
                break
            if q == p:
                continue
            six.add(p2 * q)
    if not six:
        return None
    # find smallest n such that n, n+1, n+2 in six
    # iterate sorted candidates
    for n in sorted(six):
        if (n + 1) in six and (n + 2) in six:
            return n
    return None

def main():
    limit = 100_000
    max_limit = 10_000_000
    while limit <= max_limit:
        ans = find_triple(limit)
        if ans is not None:
            print(ans)
            return
        # increase limit and try again
        limit *= 10
    # Fallback: if not found within max_limit, try doubling up to a larger cap
    limit = max_limit * 2
    max_limit2 = 50_000_000
    while limit <= max_limit2:
        ans = find_triple(limit)
        if ans is not None:
            print(ans)
            return
        limit *= 2
    # If still not found, exit with failure (should not happen for reasonable bounds)
    print("0")

if __name__ == "__main__":
    main()

