#!/usr/bin/env python3
import itertools

def count_perms(n=9):
    count = 0
    for p in itertools.permutations(range(1, n+1)):
        ok = True
        for i, val in enumerate(p, start=1):
            if abs(val - i) == 1:
                ok = False
                break
        if ok:
            count += 1
    return count

if __name__ == "__main__":
    print(count_perms(9))

