# Compute f(n): number of ordered compositions of n using parts 1,3,5
# Then print f(2026) mod 1000. Direct dynamic programming, exact integers.

def main():
    n = 2026
    parts = (1,3,5)
    f = [0] * (n+1)
    f[0] = 1
    for i in range(1, n+1):
        s = 0
        for p in parts:
            if i - p >= 0:
                s += f[i-p]
        f[i] = s
    print(f[n] % 1000)

if __name__ == "__main__":
    main()

# Compute f(n) where f(n) = number of ordered compositions of n using parts 1,3,5.
# Recurrence: f(0)=1, f(n)=f(n-1)+f(n-3)+f(n-5) with f(n)=0 for n<0.
# Print f(2026) mod 1000.

def main():
    n = 2026
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        total = 0
        if i - 1 >= 0:
            total += dp[i - 1]
        if i - 3 >= 0:
            total += dp[i - 3]
        if i - 5 >= 0:
            total += dp[i - 5]
        dp[i] = total
    print(dp[n] % 1000)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import math

def count_solutions():
    N = 2025
    limit = int(math.isqrt(N))
    count = 0
    for x in range(-limit, limit+1):
        x2 = x*x
        for y in range(-limit, limit+1):
            r = N - x2 - y*y
            if r < 0:
                continue
            s = math.isqrt(r)
            if s*s == r:
                # z = ±s, but if s == 0 there's only one value
                count += 1 if s == 0 else 2
    return count

if __name__ == "__main__":
    print(count_solutions())

