#!/usr/bin/env python3
import math

target = 2025
limit = int(math.isqrt(target))
count = 0

for x in range(-limit, limit + 1):
    xx = x * x
    for y in range(-limit, limit + 1):
        rem = target - xx - y*y
        if rem < 0:
            continue
        s = math.isqrt(rem)
        if s * s == rem:
            # z = ±s, but if s == 0 only one value
            count += 1 if s == 0 else 2

print(count)

# Count integer solutions (x,y,z) with x^2 + y^2 + z^2 = 2025 by direct computation
def main():
    target = 2025
    limit = int(target**0.5)  # 45
    count = 0
    for x in range(-limit, limit + 1):
        xx = x * x
        for y in range(-limit, limit + 1):
            yy = y * y
            for z in range(-limit, limit + 1):
                if xx + yy + z * z == target:
                    count += 1
    print(count)

if __name__ == "__main__":
    main()

